// Turn whatever the model returned into fields Telegram can accept.
//
// Models wrap JSON in code fences, add a sentence before it, or return prose
// when they forget the instruction. All three are handled here rather than
// letting a malformed message reach the chat.

const raw = String($json.output ?? $json.text ?? '').trim();

const parsed = (() => {
  const fenced = raw.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidate = (fenced ? fenced[1] : raw).trim();
  const braced = candidate.slice(candidate.indexOf('{'), candidate.lastIndexOf('}') + 1);
  try {
    return JSON.parse(braced);
  } catch {
    return null;
  }
})();

// Telegram's HTML mode rejects unescaped angle brackets and ampersands.
const escapeHtml = (value) =>
  String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

const headline = escapeHtml(parsed?.headline || 'AI news update');
const paragraphs = Array.isArray(parsed?.paragraphs)
  ? parsed.paragraphs.map(escapeHtml)
  // No usable JSON: send the model's prose rather than nothing.
  : [escapeHtml(raw.slice(0, 1500))];
const why = parsed?.whyItMatters ? escapeHtml(parsed.whyItMatters) : '';
const source = typeof parsed?.sourceUrl === 'string' ? parsed.sourceUrl : '';

const parts = [`<b>${headline}</b>`, '', paragraphs.join('\n\n')];
if (why) parts.push('', `<i>${why}</i>`);
if (source) parts.push('', escapeHtml(source));

// Telegram rejects messages over 4096 characters.
let message = parts.join('\n');
if (message.length > 4000) message = `${message.slice(0, 3997)}...`;

return [{
  json: {
    headline,
    message,
    sourceUrl: source,
    usedFallback: parsed === null,
  },
}];
